const deck = await figma.getNodeByIdAsync('466:6418');
let page = deck;
while (page && page.type !== 'PAGE') page = page.parent;

// Switch to that page to read contents
await figma.setCurrentPageAsync(page);

// Page children bounds to find free space
const kids = page.children.map(c => ({ id: c.id, name: c.name.slice(0,40), type: c.type, x: Math.round(c.x), y: Math.round(c.y), w: Math.round(c.width), h: Math.round(c.height) }));

// Sample text styles from the Brand Identity slide (466:6055) and keyword slide (466:5759)
function sampleTexts(nodeId) {
  return figma.getNodeByIdAsync(nodeId).then(n => {
    if (!n) return [];
    const texts = n.findAllWithCriteria({ types: ['TEXT'] }).slice(0, 14);
    return texts.map(t => {
      const f = t.fills && t.fills[0] && t.fills[0].type === 'SOLID' ? t.fills[0].color : null;
      return {
        chars: t.characters.slice(0, 30),
        font: t.fontName !== figma.mixed ? t.fontName.family + ' / ' + t.fontName.style : 'MIXED',
        size: t.fontSize !== figma.mixed ? t.fontSize : 'MIXED',
        color: f ? [Math.round(f.r*255), Math.round(f.g*255), Math.round(f.b*255)] : null,
        align: t.textAlignHorizontal
      };
    });
  });
}
const identityTexts = await sampleTexts('466:6055');
const keywordTexts = await sampleTexts('466:5759');

// Pill style: find small frames with fills inside 466:6055
const idSlide = await figma.getNodeByIdAsync('466:6055');
const pills = idSlide.findAllWithCriteria({ types: ['FRAME'] })
  .filter(fr => fr.height < 40 && fr.width < 300)
  .slice(0, 4)
  .map(fr => {
    const f = fr.fills && fr.fills[0] && fr.fills[0].type === 'SOLID' ? fr.fills[0].color : null;
    return { name: fr.name.slice(0,30), w: Math.round(fr.width), h: Math.round(fr.height), radius: fr.cornerRadius, fill: f ? [Math.round(f.r*255), Math.round(f.g*255), Math.round(f.b*255)] : null, padL: fr.paddingLeft, layoutMode: fr.layoutMode };
  });

// Slide background fill
const slideBg = idSlide.fills && idSlide.fills[0] && idSlide.fills[0].type === 'SOLID' ? idSlide.fills[0].color : null;

// Available Pretendard-ish fonts
const fonts = await figma.listAvailableFontsAsync();
const fams = [...new Set(fonts.map(f => f.fontName.family))];
const relevant = fams.filter(f => /pretendard|wanted|gothic a1|noto sans kr/i.test(f));
const pretendardStyles = fonts.filter(f => f.fontName.family === 'Pretendard').map(f => f.fontName.style);

return {
  pageName: page.name, pageId: page.id,
  pageChildren: kids,
  slideBg: slideBg ? [Math.round(slideBg.r*255), Math.round(slideBg.g*255), Math.round(slideBg.b*255)] : null,
  identityTexts, keywordTexts, pills,
  relevantFonts: relevant, pretendardStyles
};

