const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);

// ---- fonts: try deck font Wanted Sans, fallback Pretendard ----
let FAM = 'Wanted Sans';
const STYLES = ['Bold','SemiBold','Medium','Regular'];
try { for (const st of STYLES) await figma.loadFontAsync({family: FAM, style: st}); }
catch(e) { FAM = 'Pretendard'; for (const st of STYLES) await figma.loadFontAsync({family: FAM, style: st}); }

// ---- helpers ----
const C = h => ({ r: ((h>>16)&255)/255, g: ((h>>8)&255)/255, b: (h&255)/255 });
const solid = h => [{ type:'SOLID', color: C(h) }];
function T(chars, style, size, hex, align) {
  const t = figma.createText();
  t.fontName = { family: FAM, style };
  t.characters = chars;
  t.fontSize = size;
  t.fills = solid(hex);
  t.textAlignHorizontal = align || 'LEFT';
  return t;
}
function pill(label) {
  const p = figma.createAutoLayout('HORIZONTAL');
  p.paddingLeft = p.paddingRight = 12; p.paddingTop = p.paddingBottom = 6;
  p.cornerRadius = 8;
  p.fills = solid(0xFFE5B7);
  p.appendChild(T(label, 'Bold', 16, 0x1A1A1A));
  return p;
}
function card(label, body, size, width, center) {
  const c = figma.createAutoLayout('VERTICAL');
  c.itemSpacing = 18;
  c.paddingTop = c.paddingBottom = 32; c.paddingLeft = c.paddingRight = 32;
  c.cornerRadius = 16;
  c.fills = solid(0xFFFFFF);
  c.strokes = solid(0xECECEC); c.strokeWeight = 1;
  c.counterAxisAlignItems = center ? 'CENTER' : 'MIN';
  c.appendChild(pill(label));
  const b = T(body, 'SemiBold', size, 0x1A1A1A, center ? 'CENTER' : 'LEFT');
  c.appendChild(b);
  if (width) {
    c.resize(width, c.height);
    c.primaryAxisSizingMode = 'AUTO';
    b.layoutSizingHorizontal = 'FILL';
    b.textAutoResize = 'HEIGHT';
  }
  return c;
}
function slide(name, eyebrow) {
  const s = figma.createAutoLayout('VERTICAL');
  s.name = name;
  s.resize(1920, 1080);
  s.paddingTop = 48; s.paddingBottom = 36; s.paddingLeft = 80; s.paddingRight = 80;
  s.primaryAxisAlignItems = 'SPACE_BETWEEN';
  s.counterAxisAlignItems = 'CENTER';
  s.fills = solid(0xF8F8F8);
  s.appendChild(T(eyebrow, 'Medium', 20, 0xADADAD, 'CENTER'));
  const content = figma.createAutoLayout('VERTICAL');
  content.counterAxisAlignItems = 'CENTER';
  content.fills = [];
  s.appendChild(content);
  s.appendChild(T('SERENDI · BIS Verbal Wash · 2026.11.16', 'Medium', 14, 0xC4C4C4, 'CENTER'));
  return { s, content };
}

// ---- section ----
const sec = figma.createSection();
sec.name = '▶ BIS 버벌 확정 — 워싱 장표 (Claude · 11.16)';
sec.x = 21000; sec.y = 22648;
sec.resizeWithoutConstraints(6480, 2640);
sec.fills = solid(0xFFFFFF);

// ---- S1: Conception Keyword (washed) ----
const s1 = slide('BIS-01 Conception Keyword (워싱)', 'Brand Conception Keyword');
s1.content.itemSpacing = 36;
s1.content.appendChild(T('나를 가장 잘 아는 연애 파트너', 'Bold', 96, 0x1A1A1A, 'CENTER'));
s1.content.appendChild(T('나에게 맞는 연애와 사람을 찾도록 돕는,\n가장 가까운 상담자이자 파트너, 세렌디', 'SemiBold', 30, 0x1A1A1A, 'CENTER'));
s1.content.appendChild(T('WASH · 주선자 → 파트너  |  윌유(인연 큐레이터·디지털 주선자) 카테고리 동화 방지 — 중개자가 아닌 내 편', 'Medium', 18, 0x9FA0A9, 'CENTER'));
sec.appendChild(s1.s); s1.s.x = 120; s1.s.y = 120;

// ---- S2: Verbal Hierarchy ----
const s2 = slide('BIS-02 버벌 위계', 'Brand Verbal Identity System');
s2.content.itemSpacing = 28;
s2.content.appendChild(T('버벌 위계 Verbal Hierarchy', 'Bold', 36, 0x1A1A1A, 'CENTER'));
function hrow(label, main, mainStyle, mainSize, note) {
  const r = figma.createAutoLayout('HORIZONTAL');
  r.itemSpacing = 24; r.counterAxisAlignItems = 'CENTER'; r.fills = [];
  r.appendChild(pill(label));
  r.appendChild(T(main, mainStyle, mainSize, 0x1A1A1A));
  if (note) r.appendChild(T(note, 'Medium', 18, 0x9FA0A9));
  return r;
}
s2.content.appendChild(hrow('Brand Slogan', '우리 모두는 사랑할 자격이 있다 — Worthy of Love', 'SemiBold', 30, '믿음 · 캄페인'));
s2.content.appendChild(hrow('Brand Essence', '나다운 연애의 발견', 'Bold', 44, '본질'));
s2.content.appendChild(T('↓  발견된 것이, 시작된다', 'Medium', 18, 0xD99A3D, 'CENTER'));
s2.content.appendChild(hrow('Brand Tagline', '가장 나다운 연애의 시작, 세렌디', 'Bold', 36, '선언 · 네임 락업'));
s2.content.appendChild(hrow('Signature', '가장 나다울 때, 나다운 연애를, 날 알아주는 인연과. 세렌디.', 'SemiBold', 28, '여정 · 클로징'));
sec.appendChild(s2.s); s2.s.x = 2280; s2.s.y = 120;

// ---- S3: BIS slot cards ----
const s3 = slide('BIS-03 브랜드 아이덴티티 (확정)', 'Brand Verbal Identity System');
s3.content.itemSpacing = 24;
s3.content.appendChild(T('브랜드 아이덴티티 — BIS 확정', 'Bold', 36, 0x1A1A1A, 'CENTER'));
s3.content.appendChild(card('Brand Essence', '나다운 연애의 발견', 44, 1280, true));
s3.content.appendChild(card('Brand Definition', '세렌디는 ‘나’라는 사람의 가장 사랑스러운(Lovable) 생각과 취향을 발견하게 하고,\n그 발견을 관계의 가능성으로 잇는 소개팅 서비스다.', 27, 1280, true));
const row3 = figma.createAutoLayout('HORIZONTAL');
row3.itemSpacing = 24; row3.fills = [];
row3.appendChild(card('Brand Vision', '자신의 모습 그대로, 잘 맞는 사람과\n자연스럽게 만나는 세상', 21, 410, true));
row3.appendChild(card('Brand Mission', '나를 이해하는 대화에서 시작해,\n만남의 모든 과정에 함께한다', 21, 410, true));
row3.appendChild(card('Brand Core Value', '나를 먼저 발견하는 경험이,\n곱 신뢰가 된다', 21, 410, true));
s3.content.appendChild(row3);
sec.appendChild(s3.s); s3.s.x = 4440; s3.s.y = 120;

return {
  fontUsed: FAM,
  sectionId: sec.id,
  createdNodeIds: [sec.id, s1.s.id, s2.s.id, s3.s.id],
  bounds: { s1: [s1.s.x, s1.s.y, s1.s.width, s1.s.height], s2: [s2.s.x, s2.s.y], s3: [s3.s.x, s3.s.y] }
};

