input.code:
const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);

const FAM = 'Pretendard';
for (const st of ['Bold','SemiBold','Medium','Regular']) await figma.loadFontAsync({family: FAM, style: st});

const C = h => ({ r: ((h>>16)&255)/255, g: ((h>>8)&255)/255, b: (h&255)/255 });
const solid = h => [{ type:'SOLID', color: C(h) }];
function T(chars, style, size, hex, align) {
  const t = figma.createText();
  t.fontName = { family: FAM, style };
  t.characters = chars; t.fontSize = size; t.fills = solid(hex);
  t.textAlignHorizontal = align || 'LEFT';
  return t;
}
function pill(label) {
  const p = figma.createAutoLayout('HORIZONTAL');
  p.paddingLeft = p.paddingRight = 12; p.paddingTop = p.paddingBottom = 6;
  p.cornerRadius = 8; p.fills = solid(0xFFE5B7);
  p.appendChild(T(label, 'Bold', 16, 0x1A1A1A));
  return p;
}
function slide(name, eyebrow) {
  const s = figma.createAutoLayout('VERTICAL');
  s.name = name; s.resize(1920, 1080);
  s.paddingTop = 48; s.paddingBottom = 36; s.paddingLeft = 80; s.paddingRight = 80;
  s.primaryAxisAlignItems = 'SPACE_BETWEEN'; s.counterAxisAlignItems = 'CENTER';
  s.fills = solid(0xF8F8F8);
  s.appendChild(T(eyebrow, 'Medium', 20, 0xADADAD, 'CENTER'));
  const content = figma.createAutoLayout('VERTICAL');
  content.counterAxisAlignItems = 'CENTER'; content.fills = [];
  s.appendChild(content);
  s.appendChild(T('SERENDI · BIS Verbal Wash · 2026.11.16', 'Medium', 14, 0xC4C4C4, 'CENTER'));
  return { s, content };
}

const sec = await figma.getNodeByIdAsync('481:8');

// ---- typo fixes in S2/S3 ----
const fixes = [];
for (const t of sec.findAllWithCriteria({ types: ['TEXT'] })) {
  if (t.characters.includes('캄페인')) { t.characters = t.characters.replace('캄페인','캠페인'); fixes.push(t.id); }
  if (t.characters.includes('곱 신뢰가')) { t.characters = t.characters.replace('곱 신뢰가','곧 신뢰가'); fixes.push(t.id); }
}

// ---- S4: 3줄 활용 배치 ----
const s4 = slide('BIS-04 Tagline·Slogan·Signature 활용', 'Brand Verbal Identity System');
s4.content.itemSpacing = 24;
s4.content.appendChild(T('세 문장, 세 자리 — 활용 배치', 'Bold', 36, 0x1A1A1A, 'CENTER'));
function useCard(label, main, usage) {
  const c = figma.createAutoLayout('VERTICAL');
  c.itemSpacing = 14; c.paddingTop = c.paddingBottom = 30; c.paddingLeft = c.paddingRight = 36;
  c.cornerRadius = 16; c.fills = solid(0xFFFFFF); c.strokes = solid(0xECECEC); c.strokeWeight = 1;
  c.appendChild(pill(label));
  const m = T(main, 'SemiBold', 32, 0x1A1A1A);
  c.appendChild(m);
  c.appendChild(T(usage, 'Regular', 19, 0x9FA0A9));
  c.resize(1420, c.height); c.primaryAxisSizingMode = 'AUTO';
  m.layoutSizingHorizontal = 'FILL'; m.textAutoResize = 'HEIGHT';
  return c;
}
s4.content.appendChild(useCard('Brand Tagline', '가장 나다운 연애의 시작, 세렌디', '장기 · 로고 락업 · 앱스토어 · 상시 접점'));
s4.content.appendChild(useCard('Brand Slogan', '우리 모두는 사랑할 자격이 있다 — Worthy of Love', '단기 · 론칭 캠페인 · 브랜드 필름 · 매니페스토 헤드라인'));
s4.content.appendChild(useCard('Signature', '가장 나다울 때, 나다운 연애를, 날 알아주는 인연과. 세렌디.', '매니페스토 클로징 · 필름 엔딩 · 키비주얼'));
sec.appendChild(s4.s); s4.s.x = 120; s4.s.y = 1440;

// ---- S5: Lexicon ----
const s5 = slide('BIS-05 통제 어휘 Lexicon', 'Brand Lexicon');
s5.content.itemSpacing = 0;
s5.content.appendChild(T('통제 어휘 — 쓰는 말 / 안 쓰는 말', 'Bold', 36, 0x1A1A1A, 'CENTER'));
const gap = figma.createFrame(); gap.resize(10, 26); gap.fills = [];
s5.content.appendChild(gap);
const table = figma.createAutoLayout('VERTICAL');
table.itemSpacing = 0; table.fills = solid(0xFFFFFF);
table.cornerRadius = 16; table.strokes = solid(0xECECEC); table.strokeWeight = 1;
table.paddingTop = table.paddingBottom = 12;
function lexRow(a, b, c2, header) {
  const r = figma.createAutoLayout('HORIZONTAL');
  r.itemSpacing = 0; r.fills = []; r.paddingTop = r.paddingBottom = header ? 10 : 14;
  r.paddingLeft = r.paddingRight = 36;
  const col = (txt, w, style, hex) => {
    const t = T(txt, style, header ? 18 : 22, hex);
    t.resize(w, t.height); t.textAutoResize = 'HEIGHT';
    r.appendChild(t);
  };
  col(a, 300, header ? 'Bold' : 'Medium', header ? 0xADADAD : 0x6B6B6B);
  col(b, 480, header ? 'Bold' : 'SemiBold', header ? 0xADADAD : 0x1A1A1A);
  col(c2, 560, header ? 'Bold' : 'Regular', header ? 0xADADAD : 0x9FA0A9);
  return r;
}
function divider() {
  const d = figma.createFrame(); d.resize(1412, 1); d.fills = solid(0xEFEFEF);
  return d;
}
table.appendChild(lexRow('개념', '쓴다', '안 쓴다', true));
const rows = [
  ['만날 대상', '상대 · 사람', '이성'],
  ['서비스 범주', '소개팅', '데이팅 · 매칭'],
  ['결과', '만남', '매칭 · 연결(명사)'],
  ['나를 아는 것', '자기 이해 · 자기 발견', '상대 이해와 혼용'],
  ['차별화 축', '취향 (대표 1개)', '취향·가치관·성향 나열'],
  ['노운(호칭)', '연애 파트너 · 연애 메이트', '주선자 · 큐레이터 · 매치메이커'],
  ['레지스터', '긴 글: 사랑스러움 / 짧은 라벨: 나다움', "짧은 라벨의 '사랑스러움' · '매력'"],
];
for (const [a,b,c2] of rows) { table.appendChild(divider()); table.appendChild(lexRow(a,b,c2,false)); }
s5.content.appendChild(table);
sec.appendChild(s5.s); s5.s.x = 2280; s5.s.y = 1440;

// ---- S6: Manifesto ----
const s6 = slide('BIS-06 Brand Manifesto', 'Brand Manifesto');
s6.content.itemSpacing = 28;
s6.content.appendChild(pill('Brand Manifesto'));
s6.content.appendChild(T('나다움의 발견', 'Bold', 42, 0x1A1A1A, 'CENTER'));
const body = T(
  '인간이 사랑에 빠지는 법은, 복잡하고 또 단순하다.\n\n80억의 인구, 80억 개의 취향.\n그마저도 한 사람이 단 하나의 취향만 갖고 있진 않다.\n누군가는 애니메이션을 보다가도 와인을 따르고,\n누군가는 책을 읽다가도 문득 춤을 춘다.\n\n우리는 저마다 복잡하고, 또 단순하다.\n그 복잡함과 단순함이 모여, 나라는 사람의 ‘나다움’이 된다.\n\n세렌디는 ‘나’로부터 시작한다.\n내가 무엇을 좋아하는지, 왜 좋아하는지,\n앞으로 어떻게 즐기고 싶은지, 그 길에 누구와 함께이고 싶은지 —\n나를 아는 일에서, 연애는 비로소 시작된다.\n\n나를 알아야, 나부터 사랑할 수 있다.\n그리고 우리는 모두, 사랑받을 자격이 있다.\n아직 자신의 사랑스러움을 모르는 사람에게도,\n그 사랑스러움은 반드시 누군가 알아봐 줄 것이다.\n\n세렌디는 당신의 나다움을 먼저 발견하고,\n그 반짝임을 알아줄, 또 다른 한 사람과 잇는다.\n\n당신의 가장 나다운 취향이, 곧 새로운 만남의 가능성으로.',
  'Regular', 19, 0x3A3A3A, 'CENTER');
body.lineHeight = { unit: 'PERCENT', value: 150 };
body.resize(1100, body.height); body.textAutoResize = 'HEIGHT';
s6.content.appendChild(body);
s6.content.appendChild(T('나를 먼저 발견해주는, 연애 메이트 세렌디.', 'Bold', 24, 0x1A1A1A, 'CENTER'));
sec.appendChild(s6.s); s6.s.x = 4440; s6.s.y = 1440;

return {
  typoFixedIds: fixes,
  createdNodeIds: [s4.s.id, s5.s.id, s6.s.id],
  s6Height: s6.s.height
};

