input.code:
const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);
for (const st of ['Bold','Regular']) await figma.loadFontAsync({family:'Pretendard', style: st});

const s6 = await figma.getNodeByIdAsync('482:74');
const texts = s6.findAllWithCriteria({ types: ['TEXT'] });
const mutated = [];

for (const t of texts) {
  if (t.characters === '나다움의 발견') {
    t.characters = '나다운 연애의 발견';
    mutated.push(t.id);
  } else if (t.characters.startsWith('인간이 사랑에 빠지는')) {
    t.characters = '사람이 사랑에 빠지는 일은, 복잡하고 또 단순해요.

80억의 사람, 80억 개의 취향.
그마저도 우리는 단 하나의 취향만 갖고 있진 않죠.
누군가는 애니메이션을 보다가도 와인을 따르고,
누군가는 책을 읽다가도 문득 춤을 춰요.

우리는 저마다 복잡하고, 또 단순해요.
그 복잡함과 단순함이 모여, 나라는 사람의 ‘나다움’이 돼요.

세렌디는 ‘나’에서 시작해요.
무엇을 좋아하는지, 왜 좋아하는지,
앞으로 어떻게 즐기고 싶은지, 그 길에 누구와 함께이고 싶은지 —
나를 알아가는 일에서, 연애는 비로소 시작되니까요.

나를 알아야, 나부터 사랑할 수 있어요.
그리고 우리는 모두, 사랑받을 자격이 있어요.
아직 자신의 사랑스러움을 모르는 사람에게도,
그 사랑스러움을 알아봐 줄 사람은 반드시 있어요.

세렌디는 당신의 가장 사랑스러운 생각과 취향을 먼저 발견하고,
그 반짝임을 알아줄, 또 다른 한 사람과 이어요.

당신의 가장 나다운 취향이, 곧 새로운 만남의 가능성이 되도록.';
    mutated.push(t.id);
  }
}

return { mutatedIds: mutated, slideHeight: s6.height, textCount: texts.length };

