input.code:
const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);
await figma.loadFontAsync({family:'Pretendard', style:'SemiBold'});

const s3 = await figma.getNodeByIdAsync('481:42');
const mutated = [];
for (const t of s3.findAllWithCriteria({ types: ['TEXT'] })) {
  if (t.characters.includes('사랑스러운(Lovable)')) {
    t.characters = '세렌디는 가장 ‘나’다운 생각과 취향을 발견하게 하고,\n그 ‘나다움’을 알아줄 상대와의 만남으로 잇는 소개팅 서비스다.';
    mutated.push(t.id);
  }
}
return { mutatedIds: mutated };

