const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);

// (261116) Deck section + any loose frames in the same column below it
const sec = await figma.getNodeByIdAsync('478:10055');
const out = { sectionName: sec.name, sectionBounds: { x: sec.x, y: sec.y, w: sec.width, h: sec.height }, sectionChildren: [], looseFramesBelow: [] };

function summarizeFrame(f) {
  const texts = f.findAllWithCriteria ? f.findAllWithCriteria({ types: ['TEXT'] }) : [];
  return {
    id: f.id, name: f.name.slice(0, 50), type: f.type,
    x: Math.round(f.x), y: Math.round(f.y), w: Math.round(f.width), h: Math.round(f.height),
    texts: texts.slice(0, 10).map(t => t.characters.slice(0, 80))
  };
}

for (const c of sec.children) out.sectionChildren.push(summarizeFrame(c));

// loose page-level nodes in the same x column (10000~22000), below the section top, sorted by y
const col = page.children.filter(n =>
  n.id !== sec.id && n.x > 9500 && n.x < 22500 && n.y > sec.y - 100 && n.y < sec.y + 20000
).sort((a, b) => a.y - b.y);
for (const f of col) out.looseFramesBelow.push(summarizeFrame(f));

// bottom-most edge for placement
let maxBottom = sec.y + sec.height;
for (const f of col) maxBottom = Math.max(maxBottom, f.y + f.height);
out.maxBottom = Math.round(maxBottom);

return out;

