const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);
const FAM = 'Pretendard';
for (const st of ['Bold','SemiBold','Medium','Regular']) await figma.loadFontAsync({family: FAM, style: st});

const C = h => ({ r: ((h>>16)&255)/255, g: ((h>>8)&255)/255, b: (h&255)/255 });
const solid = h => [{ type:'SOLID', color: C(h) }];
function T(chars, style, size, hex) {
  const t = figma.createText();
  t.fontName = { family: FAM, style };
  t.characters = chars; t.fontSize = size; t.fills = solid(hex);
  return t;
}

const X = 11858, PITCH = 1382, START = 32563;
const created = [];

// small label above the block
const label = T('▼ Claude 추가 (11.16) — BIS 확정 내용 이어 스케치 · 위 기존 프레임은 미수정', 'Medium', 22, 0x9FA0A9);
label.x = X; label.y = START - 60;
created.push(label.id);

function pg(idx, name, title, body) {
  const f = figma.createFrame();
  f.name = name;
  f.resize(1920, 1080);
  f.x = X; f.y = START + idx * PITCH;
  f.fills = solid(0xFFFFFF);
  const ti = T(title, 'Bold', 44, 0x1A1A1A);
  ti.x = 60; ti.y = 56; f.appendChild(ti);
  const b = T(body, 'Medium', 27, 0x3A3A3A);
  b.lineHeight = { unit: 'PERCENT', value: 158 };
  b.x = 60; b.y = 170;
  b.resize(1800, b.height); b.textAutoResize = 'HEIGHT';
  f.appendChild(b);
  created.push(f.id);
  return f;
}

pg(0, 'pg 4 (Claude) — 버벌 확정 요약', '버벌 시스템 확정 — 나다움 한 축',
'Essence   나다운 연애의 발견 — Serendipity, Destined.\nDefinition   세렌디는 가장 ‘나’다운 생각과 취향을 발견하게 하고, 그 ‘나다움’을 알아줄 상대와의 만남으로 잇는 소개팅 서비스다.\nTagline   가장 나다운 연애의 시작, 세렌디   (상시 · 매니페스토 클로징)\nSlogan   나다움을 발견한 우연이, 우리다운 인연으로   (캠페인 · 키비주얼)\nSignature   가장 나다울 때, 나다운 연애를, 날 알아주는 인연과. 세렌디.   (필름 엔딩)\n서비스 카피   취향이 겹치는 순간, 인연이 시작돼요   (앱스토어 · 퍼포먼스)\n\n※ Worthy of Love · 사랑스러움(Lovable) 어휘는 폐기 — 전부 ‘나다움’으로 통일');

pg(1, 'pg 5 (Claude) — 통제 어휘 Lexicon', '통제 어휘 — 쓰는 말 / 안 쓰는 말',
'쓴다      상대 · 사람  |  소개팅  |  만남  |  자기 이해 · 자기 발견  |  취향(대표 1개)  |  연애 파트너 · 연애 메이트  |  나다움\n\n안 쓴다   이성  |  데이팅 · 매칭  |  연결(명사)  |  주선자 · 큐레이터 · 매치메이커  |  사랑스러움 · 매력\n\n원칙      신뢰는 구조에 1회 이상 명시한다 (BVP 장표가 담당)\n          ‘주선자’ 금지 사유 = 윌유가 ‘인연 큐레이터 · 디지털 주선자’ 선점 — 같은 말을 쓰면 같은 카테고리로 읽힌다');

pg(2, 'pg 6 (Claude) — BVP', 'Brand Value Proposition — 약속 하나, 가치 셋, 신뢰로 수렴',
'Promise   나를 먼저 이해하는 대화에서 시작해, 취향이 겹치는 자리에서 상대를 만나는 소개팅\n\n① 발견   “나도 몰랐던 내 취향과 연애관을 알게 돼요”   — 대화형 AI 세렌디 · My Profile 리포트\n② 안심   “이력서 같은 자기소개 없이, 보여줄 만큼만 보여줘요”   — 프로필 이원화 (My / Meet)\n③ 만남   “어색한 첫 만남 대신, 이야깃거리가 준비된 자리에서 만나요”   — 심리스 O2O (사전 카드 · NFC · 현장)\n\n수렴      나를 이해하는 경험이, 곧 신뢰가 된다\n\n※ 세 벤핏은 화면 리뷰 Critical 페인포인트 #01 · #02 · #04를 뒤집은 것 — 근거 있는 약속');

const pg7 = pg(3, 'pg 7 (Claude) — 컬러', '컬러 — Golden Hour Sunset',
'무드      해질녘 하늘. Golden Hour(설렘) · Sunset Sky(노을과 하늘의 경계) · Afterglow(여운)\n방향      노랑~주황의 온기 + 스카이 블루. 채도는 낮추고 흰빛 섞은 파스텔\n그라디언트   위 Sky → 아래 Warm, 노을 하늘의 수직 전환. 경계는 스머징\n금지      고채도 원색(촌스러움) · 차가운 보라 단독(테크 AI 인상)\n\n시작 팔레트 (비주얼 단계에서 눈으로 조정):');
const chips = [[0xFFF7EC,'#FFF7EC Base'],[0xFFE3A9,'#FFE3A9 Warm1'],[0xFFC58B,'#FFC58B Warm2'],[0xFFA876,'#FFA876 Warm3'],[0xBFD6F0,'#BFD6F0 Sky1'],[0x9DB9E8,'#9DB9E8 Sky2'],[0x2C2C34,'#2C2C34 Ink']];
chips.forEach(([hex, name], i) => {
  const r = figma.createRectangle();
  r.resize(200, 120); r.cornerRadius = 14;
  r.fills = solid(hex);
  r.strokes = solid(0xE5E5E5); r.strokeWeight = 1;
  r.x = 60 + i * 230; r.y = 700;
  pg7.appendChild(r);
  const lb = T(name, 'Medium', 18, 0x6B6B6B);
  lb.x = 60 + i * 230; lb.y = 836;
  pg7.appendChild(lb);
});

pg(4, 'pg 8 (Claude) — 그래픽·타이포', '그래픽 모티프 · 타이포그래피',
'그래픽    Halo(빛무리) → Converging(가까워짐) → Merging(하나로) — 기존 로직 유지\n신규 장면   ‘우리다움’ — 두 사람의 Halo가 겹쳐 더 밝은 하나의 빛이 되는 순간\n            (슬로건 “나다움을 발견한 우연이, 우리다운 인연으로”의 그림 번역 = 키비주얼 후보 1순위)\n심볼      Dia-Mark 형태 유지, 렌더링만 글로우로 — Halo 월드에 녹인다\n\n타이포    Sans 단일 체계 (Serif 폐기). Pretendard · Wanted Sans\n원칙      형태는 몽글하게, 언어는 선명하게 — 위계는 웨이트와 크기로만');

pg(5, 'pg 9 (Claude) — 목업 3장면', '목업 핵심 3장면 (비주얼 초안 우선순위)',
'① 온보딩 첫 대화   선셋 그라디언트 위에 세렌디가 건네는 첫 질문 — 설문이 아니라 대화로 시작\n\n② My Profile 리포트   매거진 커버처럼 소장하고 싶은 나의 취향 카드 — 모임 안 가는 유저도 앱을 쓸 이유\n\n③ O2O 사전 카드   두 사람의 취향 교집합이 빛으로 맺힌 티켓 — 만남 24시간 전 열람, 기대감과 대화 소재');

pg(6, 'pg 10 (Claude) — 다음 단계', '다음 단계',
'차주      버벌 + 비주얼 제안 패키지 클라 전송 (‘주선자 → 파트너’ 전환 근거 포함)\n전제      전략 · 방향은 11/2 주간 확정 — 이번 문서는 그 결정을 언어와 디자인으로 집행하는 것\n디렉션    Direction 01 단일안 (Direction 02 폐기)\n\n참고 문서   BIS_세렌디_버벌시스템_2026-11-16.md (99_Handoff) — 전체 확정 내용 · 결정 로그');

return { createdNodeIds: created, firstY: START, lastBottom: START + 6 * PITCH + 1080 };

