const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);
const FAM = 'Pretendard';
for (const st of ['Bold','SemiBold','Medium','Regular']) await figma.loadFontAsync({family: FAM, style: st});

const C = h => ({ r: ((h>>16)&255)/255, g: ((h>>8)&255)/255, b: (h&255)/255 });
const Ca = h => ({ ...C(h), a: 1 });
const solid = h => [{ type:'SOLID', color: C(h) }];
function T(chars, style, size, hex) {
  const t = figma.createText();
  t.fontName = { family: FAM, style };
  t.characters = chars; t.fontSize = size; t.fills = solid(hex);
  return t;
}

// ---- pg7: gradient swatches ----
const pg7 = await figma.getNodeByIdAsync('488:18');
const VERT = [[0, 1, 0], [-1, 0, 1]]; // top -> bottom
const grads = [
  ['Sunset Sky (메인)', [[0,0x9DB9E8],[0.38,0xBFD6F0],[0.62,0xFFF7EC],[0.82,0xFFE3A9],[1,0xFFC58B]]],
  ['Golden Hour', [[0,0xBFD6F0],[0.4,0xFFF7EC],[0.7,0xFFE3A9],[1,0xFFA876]]],
  ['Afterglow (여운)', [[0,0xFFF7EC],[0.6,0xFFE3A9],[1,0xFFC58B]]],
];
grads.forEach(([name, stops], i) => {
  const r = figma.createRectangle();
  r.name = 'gradient/' + name;
  r.resize(560, 150); r.cornerRadius = 14;
  r.x = 60 + i * 600; r.y = 884;
  r.fills = [{ type: 'GRADIENT_LINEAR', gradientTransform: VERT, gradientStops: stops.map(([p, h]) => ({ position: p, color: Ca(h) })) }];
  r.strokes = solid(0xE5E5E5); r.strokeWeight = 1;
  pg7.appendChild(r);
  const lb = T(name, 'Medium', 18, 0x6B6B6B);
  lb.x = 60 + i * 600; lb.y = 1042;
  pg7.appendChild(lb);
});

// ---- pg11: print color lock-in guide ----
const f = figma.createFrame();
f.name = 'pg 11 (Claude) — 인쇄 컬러 락인';
f.resize(1920, 1080);
f.x = 11858; f.y = 32563 + 7 * 1382;
f.fills = solid(0xFFFFFF);
const ti = T('컬러 락인 — 현장 애플리케이션 인쇄 가이드 (초안)', 'Bold', 44, 0x1A1A1A);
ti.x = 60; ti.y = 56; f.appendChild(ti);
const b = T(
'원칙   화면은 HEX, 인쇄는 CMYK + 별색 — 같은 색을 세 겹으로 정의해 어디서 찍어도 같은 색이 나오게 한다\n\n1) 컬러 정의 3중화   HEX(디지털) / CMYK 변환값(일반 인쇄) / Pantone 근사(정밀 락인 — 칩북 대조로 확정)\n     Warm1 #FFE3A9 → C0 M12 Y38 K0  ·  Warm2 #FFC58B → C0 M26 Y48 K0  ·  Warm3 #FFA876 → C0 M40 Y55 K0\n     Sky1 #BFD6F0 → C22 M10 Y0 K0  ·  Sky2 #9DB9E8 → C35 M20 Y0 K0\n     텍스트: 소형은 K100 단색(핀트 틀어짐 방지) · 대형 면은 리치블랙 C30 M20 Y0 K90\n     ※ 수치는 변환 초안 — 교정쇄 감리로 확정한다\n\n2) 그라디언트 인쇄 규칙   현장에서 재생성 금지. 마스터 에셋(300dpi 이상, CMYK 프로파일 내장)만 사용\n     소형 카드(명함~엽서 크기)는 밴딩 위험 — 2-stop 이하로 단순화하거나 단색 배경 + 그라디언트 포인트로 대체\n\n3) 용지   저채도 파스텔은 비코팅지에서 가라앉는다 — 카드류는 백색지 + 무광 코팅 권장, 미색지 금지\n\n4) 프로파일   작업 sRGB / 인쇄 Coated FOGRA39 (국내 인쇄소 기준이면 Japan Color 2001) 명시\n\n5) 감리 체크 4가지   그라디언트 밴딩 · Warm3 탁해짐 · Sky 계열이 보라로 틀어짐 · 소형 텍스트 핀트\n\n적용 대상   사전 카드 · 질문 카드 · NFC 큐카드 · 현장 포스터 · 네임택 — 로테이션 소개팅 현장 콜래터럴 전체',
'Medium', 26, 0x3A3A3A);
b.lineHeight = { unit: 'PERCENT', value: 152 };
b.x = 60; b.y = 170;
b.resize(1800, b.height); b.textAutoResize = 'HEIGHT';
f.appendChild(b);

return { pg7GradientsAdded: 3, pg11Id: f.id, pg11Y: f.y };

