const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);

const node = await figma.getNodeByIdAsync('489:14');
const nodeInfo = node ? { id: node.id, type: node.type, name: node.name.slice(0,60), x: Math.round(node.x), y: Math.round(node.y), w: Math.round(node.width), h: Math.round(node.height) } : null;
let nodeTexts = [];
if (node && 'findAllWithCriteria' in node) {
  nodeTexts = node.findAllWithCriteria({ types: ['TEXT'] }).slice(0, 20).map(t => t.characters.slice(0, 100));
} else if (node && node.type === 'TEXT') {
  nodeTexts = [node.characters.slice(0, 2000)];
}

// sweep page for stale verbal strings
const STALE = ['사랑할 자격', 'Worthy of Love', '사랑스러운(Lovable)', '연애 주선자', '나다움의 발견'];
const hits = [];
for (const t of page.findAllWithCriteria({ types: ['TEXT'] })) {
  for (const s of STALE) {
    if (t.characters.includes(s)) {
      // find top-level ancestor for location context
      let top = t;
      while (top.parent && top.parent.type !== 'PAGE' && top.parent.type !== 'SECTION') top = top.parent;
      hits.push({ textId: t.id, stale: s, container: top.name.slice(0,50), containerId: top.id, snippet: t.characters.slice(0, 70) });
      break;
    }
  }
}
return { nodeInfo, nodeTextsPreview: nodeTexts.slice(0,8), staleHits: hits };

