const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);
const FAM = 'Pretendard';
for (const st of ['Bold','SemiBold','Medium','Regular']) await figma.loadFontAsync({family: FAM, style: st});
const C = h => ({ r: ((h>>16)&255)/255, g: ((h>>8)&255)/255, b: (h&255)/255 });
const solid = h => [{ type:'SOLID', color: C(h) }];
const log = { fixed: [], deleted: [], moved: [], created: [] };

// ---- 1) BIS-04 (482:8): slogan row + usage lines ----
const s4 = await figma.getNodeByIdAsync('482:8');
for (const t of s4.findAllWithCriteria({ types: ['TEXT'] })) {
  const c = t.characters;
  if (c.includes('사랑할 자격')) {
    t.characters = '나다움을 발견한 우연이, 우리다운 인연으로';
    log.fixed.push('BIS-04 slogan main');
  } else if (c.includes('론칭 캠페인 · 브랜드 필름')) {
    t.characters = '캠페인 · 키비주얼(두 Halo 겹침 장면) · Serendipity, Destined.와 락업';
    log.fixed.push('BIS-04 slogan usage');
  } else if (c.includes('장기 · 로고 락업')) {
    t.characters = '장기 · 로고 락업 · 앱스토어 · 상시 접점 · 매니페스토 클로징';
    log.fixed.push('BIS-04 tagline usage');
  } else if (c.includes('매니페스토 클로징 · 필름 엔딩')) {
    t.characters = '필름 엔딩 · 키비주얼';
    log.fixed.push('BIS-04 signature usage');
  }
}

// ---- 2) BIS-05 (482:28): register row ----
const s5 = await figma.getNodeByIdAsync('482:28');
for (const t of s5.findAllWithCriteria({ types: ['TEXT'] })) {
  const c = t.characters;
  if (c.includes('긴 글: 사랑스러움')) {
    t.characters = '나다움 (전면 통일)';
    log.fixed.push('BIS-05 register use');
  } else if (c.includes("짧은 라벨의 '사랑스러움'")) {
    t.characters = '사랑스러움 · 매력 (전면 금지)';
    log.fixed.push('BIS-05 register avoid');
  }
}

// ---- 3) delete pg 10 (다음 단계) ----
const pg10 = await figma.getNodeByIdAsync('488:38');
if (pg10) { pg10.remove(); log.deleted.push('pg 10 다음 단계'); }

// ---- 4) move pg 11 (인쇄 락인) up into pg10 slot ----
const pg11 = await figma.getNodeByIdAsync('491:14');
if (pg11) { pg11.y = 32563 + 6 * 1382; pg11.name = 'pg 10 (Claude) — 인쇄 컬러 락인'; log.moved.push('인쇄 락인 → pg10 슬롯 (y ' + pg11.y + ')'); }

// ---- 5) blank design frames for 다인D ----
for (let i = 0; i < 3; i++) {
  const f = figma.createFrame();
  f.name = '디자인 장표 0' + (i + 1) + ' (다인D 작업용 — 빈 프레임)';
  f.resize(1920, 1080);
  f.x = 11858; f.y = 32563 + (7 + i) * 1382;
  f.fills = solid(0xFFFFFF);
  log.created.push(f.id);
}

return log;

