const page = await figma.getNodeByIdAsync('38:27');
await figma.setCurrentPageAsync(page);
const FAM = 'Pretendard';
for (const st of ['Bold','SemiBold','Medium','Regular']) await figma.loadFontAsync({family: FAM, style: st});
const C = h => ({ r: ((h>>16)&255)/255, g: ((h>>8)&255)/255, b: (h&255)/255 });
const solid = h => [{ type:'SOLID', color: C(h) }];
function T(chars, style, size, hex) {
  const t = figma.createText();
  t.fontName = { family: FAM, style };
  t.characters = chars; t.fontSize = size; t.fills = solid(hex);
  return t;
}

const f = figma.createFrame();
f.name = 'pg 7-A (Claude) — UI Foundation 컬러 토큰 (디벨롭 시안)';
f.resize(1920, 1080);
f.x = 14080; f.y = 36709;
f.fills = solid(0xFFFFFF);

const ti = T('UI Foundation — 컬러 토큰 (Golden Hour Sunset 확장)', 'Bold', 40, 0x1A1A1A);
ti.x = 60; ti.y = 50; f.appendChild(ti);

const scales = [
  ['Warm (Apricot) — 브랜드 중심축', [
    ['50','FFF9F0'],['100','FFEFD8'],['200','FFE3A9'],['300','FFD398'],['400','FFC58B'],['500','FFA876'],['600','F28B55'],['700','D96F3D'],['800','A84E26']
  ]],
  ['Sky — 보조축 · 링크/정보', [
    ['50','F3F7FC'],['100','E2ECF8'],['200','BFD6F0'],['300','9DB9E8'],['400','7FA3DC'],['500','6189C9'],['600','4A6EAE'],['700','37538B'],['800','273D68']
  ]],
  ['Neutral (Warm Gray) — 텍스트/보더', [
    ['50','FAF8F5'],['100','F1EEE9'],['200','E3DFD8'],['300','C9C4BC'],['400','A8A39B'],['500','85817A'],['600','5F5C56'],['700','3E3C38'],['800','2C2C34']
  ]],
];

let y = 130;
for (const [label, steps] of scales) {
  const lb = T(label, 'SemiBold', 20, 0x1A1A1A);
  lb.x = 60; lb.y = y; f.appendChild(lb);
  steps.forEach(([step, hex], i) => {
    const r = figma.createRectangle();
    r.name = label.split(' ')[0] + '/' + step;
    r.resize(180, 72); r.cornerRadius = 10;
    r.x = 60 + i * 196; r.y = y + 34;
    r.fills = solid(parseInt(hex, 16));
    r.strokes = solid(0xE8E8E8); r.strokeWeight = 1;
    f.appendChild(r);
    const sl = T(step + '  #' + hex, 'Medium', 13, 0x85817A);
    sl.x = 60 + i * 196; sl.y = y + 112;
    f.appendChild(sl);
  });
  y += 170;
}

// semantic tokens (left) + principles (right)
const sem = T(
'시맨틱 토큰 (라이트 모드)\n\nbg.base          Warm/50  — 화면 바탕 (크림)\nbg.surface       #FFFFFF  — 카드·시트\nbg.warm          Warm/100 — 강조 서피스·칩\nprimary          Warm/600 — CTA 버튼 배경\nprimary.pressed  Warm/700\non.primary       Neutral/800 — CTA 텍스트는 잉크 (화이트 금지)\naccent.link      Sky/600  — 링크·정보성 액션\ntext.primary     Neutral/800   text.secondary  Neutral/500\ntext.disabled    Neutral/300   border  Neutral/200   divider  Neutral/100\nstate.success #4CAF7D · state.warning Warm/500 · state.error #E25C5C · state.info Sky/500',
'Medium', 20, 0x3A3A3A);
sem.lineHeight = { unit: 'PERCENT', value: 152 };
sem.x = 60; sem.y = y + 10;
sem.resize(900, sem.height); sem.textAutoResize = 'HEIGHT';
f.appendChild(sem);

const pr = T(
