DST="/Users/dainpark/Library/CloudStorage/GoogleDrive-manypeoplepark@gmail.com/My Drive/⛺️ WCAMP/세렌디/99_Handoff"
cp "$SRC" "$DST/SESSION_BIS버벌-디자인_2026-11-16~17_full.jsonl"
python3 - "$SRC" "$DST/SESSION_BIS버벌-디자인_2026-11-16~17_slim.jsonl" <<'EOF'
import json, sys
src, dst = sys.argv[1], sys.argv[2]
def strip(obj):
    if isinstance(obj, dict):
        out = {}
        for k, v in obj.items():
            if k in ('data', 'base64') and isinstance(v, str) and len(v) > 5000:
                out[k] = f'[stripped {len(v)} chars base64]'
            elif k == 'source' and isinstance(v, dict) and v.get('type') == 'base64':
                out[k] = {'type': 'base64', 'media_type': v.get('media_type'), 'data': f"[stripped {len(v.get('data',''))} chars]"}
            else:
                out[k] = strip(v)
        return out
    if isinstance(obj, list):
        return [strip(x) for x in obj]
    if isinstance(obj, str) and len(obj) > 200000:
        return obj[:2000] + f'...[truncated, total {len(obj)} chars]'
    return obj
n = 0
with open(src) as f, open(dst, 'w') as g:
    for line in f:
        line = line.strip()
        if not line: continue
        try:
            g.write(json.dumps(strip(json.loads(line)), ensure_ascii=False) + '\n')
            n += 1
        except json.JSONDecodeError:
            g.write(line + '\n')
print('events:', n)
EOF
ls -lh "$DST" | grep SESSION
